import pandas as pd
import numpy as np

def clean(df):
    d = df.copy()
    if 'Region' in d.columns:
        d['Region'] = d['Region'].astype('string').str.strip().str.title()
        d['Region'] = d['Region'].replace({'': pd.NA, 'Nan': pd.NA, 'None': pd.NA})
    if 'Category' in d.columns:
        d['Category'] = d['Category'].astype('string').str.strip()
    for col in ['Quantity', 'Price', 'Revenue']:
        if col in d.columns:
            d[col] = pd.to_numeric(d[col], errors='coerce')
    if 'Quantity' in d.columns:
        d['Quantity'] = d['Quantity'].abs()
    if 'Quantity' in d.columns and 'Price' in d.columns:
        d['Revenue'] = d['Quantity'] * d['Price']
    if 'Date' in d.columns:
        d['Date'] = pd.to_datetime(d['Date'], errors='coerce').dt.strftime('%Y-%m-%d')
    return d

def answer(df):
    d = clean(df)
    mask = d['Category'].astype('string').str.strip().str.casefold().eq('electronics').fillna(False)
    d = d[mask].dropna(subset=['Region'])
    out = d.groupby('Region', dropna=True)['Revenue'].sum()
    return {str(k): float(v) for k, v in out.items()}
